INSERT INTO posts (category_id,title,slug,excerpt,content,author,publish_date,status,featured,seo_title,seo_description) VALUES (1,'Five ways to make onboarding more human','five-ways-to-make-onboarding-more-human','Simple improvements that help new colleagues feel informed, welcomed, and ready.','<h2>Begin before day one</h2><p>Useful onboarding starts with clear communication, access preparation, and a realistic first-week plan.</p><h2>Assign real ownership</h2><p>Give each step an owner and invite feedback after 30, 60, and 90 days.</p>','Touhid Rahman',NOW(),'published',1,'Five ways to make onboarding more human','Practical onboarding improvements for better employee experience.');
